import{_ as t}from"./chunks/buildings.CQ8vpPwC.js";import{_ as a,o as i,c as r,a0 as o}from"./chunks/framework.DYAX5gPL.js";const l="/assets/tiles.CTpqnjx9.png",f=JSON.parse('{"title":"Vector Tiles Overview","description":"","frontmatter":{"title":"Vector Tiles Overview"},"headers":[],"relativePath":"en/api/vt-intro.md","filePath":"en/api/vt-intro.md"}'),s={name:"en/api/vt-intro.md"};function n(d,e,h,m,c,p){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><h2 id="map-tiles" tabindex="-1">Map Tiles <a class="header-anchor" href="#map-tiles" aria-label="Permalink to &quot;Map Tiles&quot;">​</a></h2><p><img src="'+l+'" alt="Map tile system"></p><p>The tile map pyramid model is a multi-resolution hierarchical model. From the bottom to the top of the tile pyramid, the resolution decreases while the geographic extent remains the same. First, determine the number of zoom levels N that the map service platform provides. Take the map image with the highest zoom level and the largest map scale as the bottom of the pyramid (level 0), and tile it: starting from the upper-left corner of the map image, cut it from left to right and top to bottom into square map tiles of the same size (e.g. 256x256 pixels), forming the level-0 tile matrix. Based on the level-0 map image, generate the level-1 map image by splitting every pixel into 2x2 pixels, and tile it into square map tiles of the same size as the previous level, forming the level-1 tile matrix. Generate the level-2 tile matrix in the same way, and so on, up to level N-1, to form the entire tile pyramid.</p><blockquote><p>Quoted from Baidu Baike.</p></blockquote><h2 id="raster-tiles-and-vector-tiles" tabindex="-1">Raster Tiles and Vector Tiles <a class="header-anchor" href="#raster-tiles-and-vector-tiles" aria-label="Permalink to &quot;Raster Tiles and Vector Tiles&quot;">​</a></h2><ul><li>Raster tiles are tiles whose content is a static image, such as png, jpg, etc.</li><li>Vector tiles are tiles whose content is vector data, including the coordinates of points, lines and polygons and optional data property values. Here is a <a href="/en/guide/vector-tile.html">brief introduction to vector tiles</a>.</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th>Raster Tiles</th><th>Vector Tiles</th></tr></thead><tbody><tr><td style="text-align:left;">Easy to produce</td><td>❌</td><td>✔</td></tr><tr><td style="text-align:left;">Attribute data</td><td>❌</td><td>✔</td></tr><tr><td style="text-align:left;">Interactive</td><td>❌</td><td>✔</td></tr><tr><td style="text-align:left;">3D support</td><td>❌</td><td>✔</td></tr><tr><td style="text-align:left;">Rendering mechanism</td><td>Simple</td><td>Complex</td></tr><tr><td style="text-align:left;">Real-time tiling</td><td>Difficult</td><td>Easy</td></tr></tbody></table><p>In summary, compared with traditional raster tiles, vector tiles have many advantages apart from a more complex rendering mechanism.</p><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><p>The vector tile format was developed by Mapbox in 2014. The latest version is 2.1.</p><h2 id="vector-tiles-and-3d" tabindex="-1">Vector Tiles and 3D <a class="header-anchor" href="#vector-tiles-and-3d" aria-label="Permalink to &quot;Vector Tiles and 3D&quot;">​</a></h2><p>Vector tiles currently store 2D data, but by combining the height values in the attribute data, 3D white-model buildings like those in the image below can be generated.</p><p><img src="'+t+'" alt="3D white model"></p><h2 id="server-side-real-time-tiling" tabindex="-1">Server-Side Real-Time Tiling <a class="header-anchor" href="#server-side-real-time-tiling" aria-label="Permalink to &quot;Server-Side Real-Time Tiling&quot;">​</a></h2><p>Because vector tiles store vector data, they can skip the server-side rendering step required by raster tiles, so generating vector tiles in real time from a spatial database is more efficient and convenient.</p><p>With server-side real-time tiling, data updates are reflected in the tiles in real time, improving the real-time responsiveness of the service and reducing data maintenance costs.</p><p>PostGIS now provides the <code>ST_AsMVT</code> SQL function, which can output query results directly in the vector tile format. Some open-source servers in the community offer real-time tiling based on database or file data.</p><p>The MapTalks solution provides the VTS server software for real-time vector tile tiling of data at the scale of hundreds of millions of records. You can find detailed information here.</p><blockquote><p>This document has been cross-checked against the @maptalks/gl-layers 2026 source code (api-notes-vt-gl.md)</p></blockquote>',20)])])}const g=a(s,[["render",n]]);export{f as __pageData,g as default};
